package org.eclipse.kura.core.keystore.crl.test;

import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.security.KeyStore;
import java.security.cert.X509CRL;
import java.util.Date;
import java.util.HashMap;
import java.util.Map;

import org.bouncycastle.asn1.x500.X500Name;
import org.eclipse.kura.configuration.ConfigurationService;
import org.eclipse.kura.core.keystore.FilesystemKeystoreServiceImpl;
import org.eclipse.kura.core.keystore.crl.CRLManager;
import org.eclipse.kura.core.testutil.pki.TestCA;
import org.eclipse.kura.core.testutil.pki.TestCA.CRLCreationOptions;
import org.eclipse.kura.core.testutil.pki.TestCA.CertificateCreationOptions;
import org.eclipse.kura.core.testutil.pki.TestCA.TestCAException;
import org.eclipse.kura.crypto.CryptoService;
import org.junit.After;
import org.junit.Rule;
import org.junit.rules.TemporaryFolder;
import org.mockito.ArgumentMatchers;
import org.mockito.Mockito;
import org.osgi.service.component.ComponentContext;
import org.osgi.service.event.EventAdmin;

public abstract class CrlKeystoreServiceTestBase {

    private static final String KEYSTORE_PASSWORD = "foo";

    @Rule
    public TemporaryFolder temporaryFolder = new TemporaryFolder();

    protected final FilesystemKeystoreServiceImpl keystoreService;
    protected final EventAdmin eventAdmin = Mockito.mock(EventAdmin.class);

    private final Map<String, Object> properties = new HashMap<>();
    private boolean active;

    protected CrlKeystoreServiceTestBase() {
        this(CrlTestKeystoreService.SHORT_DELAYS);
    }

    protected CrlKeystoreServiceTestBase(final CRLManager.Delays crlManagerDelays) {
        this.keystoreService = new CrlTestKeystoreService(crlManagerDelays);
    }

    @After
    public void deactivateKeystoreService() {
        if (this.active) {
            this.keystoreService.deactivate();
            this.active = false;
        }
    }

    protected void givenKeystoreServiceWithCrlManagement(final Map<String, Object> crlOptions) throws Exception {
        final File keystoreFile = new File(this.temporaryFolder.getRoot(), "keystore.ks");
        final KeyStore keystore = KeyStore.getInstance("jks");
        keystore.load(null, null);

        try (final FileOutputStream out = new FileOutputStream(keystoreFile)) {
            keystore.store(out, KEYSTORE_PASSWORD.toCharArray());
        }

        final CryptoService cryptoService = Mockito.mock(CryptoService.class);
        Mockito.when(cryptoService.encryptAes((char[]) ArgumentMatchers.any()))
                .thenAnswer(i -> i.getArgument(0, char[].class));
        Mockito.when(cryptoService.decryptAes((char[]) ArgumentMatchers.any()))
                .thenAnswer(i -> i.getArgument(0, char[].class));
        Mockito.when(cryptoService.getKeyStorePassword(ArgumentMatchers.any(String.class)))
                .thenReturn(KEYSTORE_PASSWORD.toCharArray());

        this.properties.put("keystore.path", keystoreFile.getAbsolutePath());
        this.properties.put("keystore.password", KEYSTORE_PASSWORD);
        this.properties.put("crl.management.enabled", true);
        this.properties.put(ConfigurationService.KURA_SERVICE_PID, "foo");
        this.properties.putAll(crlOptions);

        this.keystoreService.setConfigurationService(Mockito.mock(ConfigurationService.class));
        this.keystoreService.setEventAdmin(this.eventAdmin);
        this.keystoreService.setCryptoService(cryptoService);
        this.keystoreService.activate(Mockito.mock(ComponentContext.class), new HashMap<>(this.properties));
        this.active = true;
    }

    protected void whenCrlOptionChanges(final String key, final Object value) {
        this.properties.put(key, value);
        this.keystoreService.updated(new HashMap<>(this.properties));
    }

    protected void whenKeystoreServiceIsDeactivated() {
        this.keystoreService.deactivate();
        this.active = false;
    }

    protected static X509CRL newCrl(final String issuer, final Date thisUpdate, final Date nextUpdate)
            throws TestCAException {
        final TestCA ca = new TestCA(CertificateCreationOptions.builder(new X500Name(issuer)).build());

        return ca.generateCRL(CRLCreationOptions.builder().withStartDate(thisUpdate).withEndDate(nextUpdate).build());
    }

    protected File writeCrlFile(final String name, final X509CRL crl) throws IOException {
        final File file = new File(this.temporaryFolder.getRoot(), name);

        try (final FileOutputStream out = new FileOutputStream(file)) {
            TestCA.encodeToPEM(crl, out);
        }

        return file;
    }
}
